import random
from fractions import Fraction
from ferryfare import fare, passenger_fare, vehicle_fare


def adult(zones):
    return {1: 450, 2: 700}.get(zones, 700 + 175 * (zones - 2))


def veh(dm):
    if dm is None:
        return 0
    if dm <= 30:
        return 1200
    if dm <= 55:
        return 2600
    if dm <= 80:
        return 4800
    extra = 0
    while 80 + 10 * extra < dm:
        extra += 1
    return 4800 + 900 * extra


def half_up(x):
    return int((Fraction(x) * 2 + 1) // 2)


def oracle(zones, ages, dm, depart):
    a = adult(zones)
    pax = 0
    for age in ages:
        if age >= 16:
            pax += a
        elif age >= 5:
            pax += half_up(Fraction(a, 2))
    mins = depart[0] * 60 + depart[1]
    if 600 <= mins < 900:
        pax = half_up(Fraction(pax * 85, 100))
    total = pax + veh(dm)
    while total % 5:
        total += 1
    return total


