        self.assertEqual(fare(2, [30], depart=(9, 59)), 700)
        self.assertEqual(fare(2, [30], depart=(10, 0)), 595)
        self.assertEqual(fare(2, [30], depart=(14, 59)), 595)
        self.assertEqual(fare(2, [30], depart=(15, 0)), 700)

