        self.assertEqual(fare(3, [30, 6, 6, 6], depart=(11, 0)), 1865)
        self.assertEqual(fare(3, [30, 6, 6, 6], depart=(11, 0)), oracle(3, [30, 6, 6, 6], None, (11, 0)))

