        self.assertEqual(drop(["a", "b", "c", "d"], "b", 2), (["a", "c", "d"], 1))

    def test_drop_current(self):
        self.assertEqual(drop(["a", "b", "c", "d"], "c", 2), (["a", "b", "d"], 2))
        self.assertEqual(drop(["a", "b", "c", "d"], "a", 0), (["b", "c", "d"], 0))

    def test_drop_current_last_wraps(self):
