            lst = [f"n{i}" for i in range(n)]
            cur = rng.randrange(n)
            gone = rng.choice(lst)
            new, idx = drop(lst, gone, cur)
            if gone != lst[cur]:
                self.assertEqual(new[idx], lst[cur])
            else:
                want = lst[(cur + 1) % n] if n > 1 else None
                self.assertEqual(new[idx], want)


