def oracle(price, first_home, resident):
    d = Fraction(0)
    d += max(0, min(price, 350_000) - 180_000) * Fraction(25, 1000)
    d += max(0, min(price, 700_000) - 350_000) * Fraction(5, 100)
    d += max(0, price - 700_000) * Fraction(8, 100)
    if first_home:
