        cs = [mk("bea", 5), mk("Ann", 5), mk("anna", 5), mk("Carl", 5)]
        self.assertEqual(order(cs), ["Ann", "anna", "bea", "Carl"])

    def test_order_random_matches_sorted_key(self):
