    def test_best_slot(self):
        self.assertEqual(best_slot([(0, 3), (20, 24)], 5), (20, 24))
        self.assertEqual(best_slot([(0, 3), (20, 24)], 4), (0, 3))
        self.assertEqual(best_slot([(0, 9), (20, 40)], 3), (0, 2))
