        cs = [mk("bo", 10, 1), mk("Cy", 10, 4), mk("Al", 10, 1), mk("dee", 12), mk("al", 10, 1), mk("Zed", 3)]
        self.assertEqual(order(cs), ["dee", "Cy", "Al", "al", "bo", "Zed"])

