            cs = [mk(n, rng.randint(1, 5), rng.randint(0, 3)) for n in names]
            want = [c["name"] for c in sorted(cs, key=lambda c: (-c["roll"], -c["dex"], c["name"].lower()))]
            self.assertEqual(order(cs), want)

