    top = 0
    for text in existing:
        try:
            p = parse_label(text)
        except ValueError:
            continue
        if p["site"] == site and p["date"] == day:
            top = max(top, p["seq"])
    if top >= 9999:
        raise OverflowError("no sequence numbers left")
    return make_label(site, day, top + 1)

